import './App.css';
import Festval_Serch from "./component/Festval_Serch.js";
import Festval_CardList from "./component/Festval_CardList.js";
import moment from 'moment';
import { useState } from 'react';


const App= () => {  
  const today = moment();
  let [areaCode, setAreaCode] = useState("");
  let [monthCode, setMonthCode] = useState(today.month()+1);

  const onAreaCodeChange = (value) =>{
    setAreaCode(value);
  }
  const onMonthCodeChange = (value) =>{
    setMonthCode(value);
  }

  return (
    <section id='main_conteiner'>
      <section className='left_box'></section> {/** 프로젝트 로고삽입 */}
      <section className='right_box'>
        <Festval_Serch today = {today.year()} onAreaCodeChange = {onAreaCodeChange} onMonthCodeChange = {onMonthCodeChange}/>
        <Festval_CardList today = {today} areaCode = {areaCode} monthCode = {monthCode} />
      </section>
    </section>    
  );
}

export default App;
